{
 "what_you_observe": [
  "Tuesday, February 2. Seven pm.",
  "Phil said in the lobby: Rita. I hear you. About Alma. I'll call her from the terminal tomorrow, after I'm off the coach. I'll ask her what she wants to hear. I'll just... listen. I'll do it from a payphone with a three-minute limit and I'll do it. Goodnight.",
  "Rita records Alma at the Rialto and puts her recording on the patch.",
  "Larry said in the lobby: I'm taking the last charge off the festival board. Rialto, before it closes. Don't wait on me for the afternoon.",
  "Larry records Alma on his last charged take. The reel stays with him.",
  "You are now at Rialto.",
  "There is time for one evening visit. The ballroom lights are on and the station line is open."
 ],
 "your_own_memories": [
  {
   "what_you_did": "Rita records Alma at the Rialto and puts her recording on the patch.",
   "what_you_said": "I'm taking the afternoon. Rialto closes at six. I want to be in that booth before the lights go out for good. Don't wait up.",
   "your_intention": "Get to the Rialto before nine. Sit in the booth where Alma spent forty-two winters threading film. Record her one last time—her hands on the gate, her voice saying what she wants her daughter to know. One reel. The regional line takes it out tonight. Pittsburgh gets the voice. That is the piece. Not the party. Not the ballroom. Not the network's story. Mine."
  }
 ],
 "who_you_are_with": "your present location",
 "physical_choices": {
  "transmit_interview": "Take the regional line at the station and send any usable interview with Alma to her daughter.",
  "go_dancing": "Spend the evening at the ballroom, open to dancing with a colleague.",
  "go_to_party_for_work": "Cover the party with your notebook, without dancing.",
  "take_evening_off": "Choose a quiet evening on your own."
 }
}
